export class ValidationUtils{constructor(){this.rules={email:/^[^\s@]+@[^\s@]+\.[^\s@]+$/,phone:/^[\+]?[1-9][\d]{0,15}$/,url:/^(https?:\/\/)?([\da-z\.-]+)\.([a-z\.]{2,6})([\/\w \.-]*)*\/?$/,numeric:/^[0-9]+$/,alphabetic:/^[A-Za-z\s]+$/,alphanumeric:/^[a-zA-Z0-9\s]+$/,password:/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[A-Za-z\d@$!%*?&]{8,}$/,username:/^[a-zA-Z0-9_]{3,30}$/}}validateField(e,a={}){const s=e.value.trim(),t=e.type,r=e.name||e.id;if(!e.required&&!s)return{valid:!0,message:""};if(e.required&&!s)return{valid:!1,message:"This field is required"};const i={email:()=>this.rules.email.test(s)||"Invalid email format",tel:()=>this.rules.phone.test(s.replace(/\D/g,""))||"Invalid phone number",url:()=>this.rules.url.test(s)||"Invalid URL",password:()=>s.length>=8||"Password must be at least 8 characters","email-username":()=>this.validateEmailUsername(s)},l=i[t]||i[r];if(l){const e=l();if("string"==typeof e)return{valid:!1,message:e}}if(e.dataset.validate){const t=this.validateWithCustomRules(e,s,a);if(!t.valid)return t}return{valid:!0,message:""}}validateEmailUsername(e){return!!this.rules.email.test(e)||!!this.rules.username.test(e)||"Enter a valid email or username (3-30 characters, letters, numbers, underscores)"}validateWithCustomRules(e,a,s){const t=e.dataset.validate.split(",");for(const s of t.map(e=>e.trim())){const[t,r]=s.split(":");switch(t){case"match":const s=e.form.querySelector(`[name="${r}"]`);if(s&&a!==s.value)return{valid:!1,message:"Values do not match"};break;case"min":if(a.length<parseInt(r))return{valid:!1,message:`Minimum ${r} characters required`};break;case"max":if(a.length>parseInt(r))return{valid:!1,message:`Maximum ${r} characters allowed`};break;case"regex":try{if(!new RegExp(r).test(a))return{valid:!1,message:e.title||"Invalid format"}}catch(e){console.error("Invalid regex:",r)}}}return{valid:!0,message:""}}}